// --- FORMATTING FUNCTIONS ---
function formatResolution(width, height, device = "", focalActual = "") {
  if (width <= 0 || height <= 0) return "";
  const ratio = width / height;
  // console.log(device, width, height, ratio.toFixed(4), focalActual);
  if (
    device === "iQOO 12" ||
    device === "vivo I2220" ||
    device === "Google I2220" ||
    device === "I2220"
  ) {
    if (Math.abs(ratio - 3 / 4) < 0.02 || Math.abs(ratio - 4 / 3) < 0.02) {
      switch (focalActual) {
        case "13.3mm":
          width = 3456;
          height = 4608;
          manualFields.descrip.value = "OmniVision OV64B";
          break;
        case "6.45mm":
          width = 3072;
          height = 4096;
          manualFields.descrip.value = "OmniVision OV50H";
          break;
        case "2.32mm":
          width = 3072;
          height = 4080;
          manualFields.descrip.value = "ISOCELL S5KJN1";
          break;
        case "3.74mm":
          width = 1728;
          height = 2304;
          manualFields.descrip.value = "ISOCELL S5K3P9SP";
          break;
      }
    }
  } else if (
    device === "Xiaomi Mi A1" ||
    device === "Xiaomi Mi 5X" ||
    device === "Google Mi A1" ||
    device === "Google Mi 5X" ||
    device === "Mi A1" ||
    device === "Mi 5X" ||
    device === "Tissot"
  ) {
    if (Math.abs(ratio - 3 / 4) < 0.02 || Math.abs(ratio - 4 / 3) < 0.02) {
      switch (focalActual) {
        case "5.99mm":
        case "3.81mm":
          width = 3072;
          height = 4096;
          break;
        case "2.639mm":
        case "2.46mm":
        case "1.92mm":
          width = 1944;
          height = 2592;
          break;
      }
    }
  }
  let megapixels = (width * height) / 1000000;
  if (megapixels.toFixed(1).endsWith("0")) return `${megapixels.toFixed(0)} MP`;
  else return `${megapixels.toFixed(1)} MP`;
}

function formatFocalLength(value, device = "") {
  return value ? `${value}mm` : "";
}

function formatAperture(value, device = "") {
  if (!value) return "";
  let aperture = parseFloat(value);
  if (device === "iQOO 12") {
    if (aperture === 1.7) aperture = 1.68;
    if (aperture === 2.6) aperture = 2.57;
  }
  const rounded = aperture.toFixed(2);
  if (rounded.endsWith("00")) return `f/${parseInt(rounded).toFixed(1)}`;
  if (aperture.toFixed(2).endsWith("0")) return `f/${aperture.toFixed(1)}`;
  return `f/${rounded}`;
}

function formatShutterSpeed(value) {
  if (!value || value <= 0) return "";
  if (value >= 1) return `${value}s`;
  const reciprocal = 1 / value;
  const roundedReciprocal = Math.round(reciprocal);
  return `1/${Math.max(1, roundedReciprocal)}s`;
}
function formatIso(value) {
  if (!value) return "";
  return `ISO${value}`;
}

function displayError(message) {
  const existingError = document.querySelector(".error");
  if (existingError) existingError.remove();
  const controls = document.getElementById("errorValue");
  if (!controls) return;
  const errorElement = document.createElement("p");
  errorElement.className = "error";
  errorElement.textContent = `❌ ${message}`;
  controls.prepend(errorElement);
}

function resetDisplay() {
  frameContainer.classList.add("hidden");
  const frameContainerArray = document.getElementById("frameContainerArray");
  if (frameContainerArray) frameContainerArray.classList.add("hidden");

  placeholderText.style.display = "block";
  downloadButton.disabled = true;
  applyManualButton.disabled = true;
  previewCanvas.style.width = "auto";
  previewCanvas.style.height = "auto";
  frameContainer.style.width = "auto";
  frameContainer.style.height = "auto";

  for (const key in manualFields) {
    manualFields[key].value = "";
    manualFields[key].disabled = false;
  }

  const existingError = document.querySelector(".error");
  if (existingError) existingError.remove();

  currentExifData = {};
  imgOriginal.src = "";
  previewCanvas.width = 0;
  previewCanvas.height = 0;

  // Hapus grid multi-preview sebelumnya jika ada
  const existingMulti = frameContainerArray.querySelector(".multi-preview");
  if (existingMulti) existingMulti.remove();
}

// --- WATERMARK HANDLER ---
function handleWMSelect(e) {
  const file = e.target.files[0];
  if (!file) return;
  if (!file.type.startsWith("image/")) {
    displayError("Watermark harus berupa file gambar.");
    return;
  }

  const reader = new FileReader();
  reader.onload = function (event) {
    const newWmImage = new Image();
    newWmImage.onload = function () {
      wmImageFile = newWmImage;
      if (imgOriginal.src) applyManualData();
    };
    newWmImage.src = event.target.result;
  };
  reader.readAsDataURL(file);
}

// --- MAIN FILE HANDLER ---
function handleFileSelect(e) {
  const selectedFiles = Array.from(e.target.files);
  filesToProcess = selectedFiles.filter((f) => f.type.startsWith("image/"));

  if (filesToProcess.length !== selectedFiles.length) {
    if (filesToProcess.length > 0) {
      displayError(
        `Perhatian: Hanya file gambar yang diizinkan. (${
          selectedFiles.length - filesToProcess.length
        } file diabaikan).`,
      );
    } else {
      displayError("Unggah file gambar yang valid.");
    }
  }

  if (filesToProcess.length === 0) return resetDisplay();

  // 🔄 Reset tampilan sebelum menampilkan preview baru
  resetDisplay();

  const containerArray = document.getElementById("frameContainerArray");

  if (filesToProcess.length === 1) {
    // ✅ Mode single file
    frameContainer.classList.remove("hidden");
    containerArray.classList.add("hidden");
    Object.values(manualFields).forEach((input) => (input.disabled = false));
    loadSingleFilePreview(filesToProcess[0]);
  } else {
    // ✅ Mode multiple file
    frameContainer.classList.add("hidden");
    containerArray.classList.remove("hidden");
    // Object.keys(manualFields).forEach((key) => {
    //   manualFields[key].disabled = key !== "device" && key !== "resolution";
    // });
    applyManualButton.disabled = false;
    loadMultipleFilePreview(filesToProcess);
  }

  downloadButton.disabled = false;
  toggleAdvancedButton.disabled = false;
}

function loadSingleFilePreview(file) {
  const reader = new FileReader();
  reader.onload = (e) => {
    imgOriginal.src = e.target.result;
    imgOriginal.onload = () => {
      placeholderText.style.display = "none";
      frameContainer.classList.remove("hidden");
      multiBool = false;
      processExifData(imgOriginal, () => {
        applyManualButton.disabled = true;
        downloadButton.textContent = `${file.name}`;
        applyManualData();
        setTimeout(() => {
          downloadButton.disabled = false;
          toggleAdvancedButton.disabled = false;
          downloadButton.textContent = "Simpan";
        }, 800);
      });
      applyManualData();
    };
  };
  reader.readAsDataURL(file);
}

/**
 * Memuat dan menampilkan pratinjau thumbnail untuk banyak file gambar yang dipilih.
 *
 * Catatan: Fungsi ini mengasumsikan variabel global seperti:
 * - currentExifData, processExifData, createFramedImage, applyManualData
 * - frameContainerArray, frameContainer, placeholderText
 * - processedImages (objek untuk menyimpan data gambar)
 *
 * @param {FileList} files - Daftar File (gambar) yang dipilih oleh user.
 */
function loadMultipleFilePreview(files) {
  const containerArray = document.getElementById("frameContainerArray");
  const frameContainer = document.getElementById("frameContainer");
  const placeholderText = document.getElementById("placeholderText");

  if (!containerArray || !frameContainer || !placeholderText) {
    console.error("Elemen container atau placeholder tidak ditemukan.");
    return;
  }

  // 1. Persiapan UI utama
  containerArray.classList.remove("hidden");
  frameContainer.classList.add("hidden");
  placeholderText.style.display = "none";

  // Bersihkan preview sebelumnya
  const existingPreviewWrapper = containerArray.querySelector(".multi-preview");
  if (existingPreviewWrapper) existingPreviewWrapper.remove();

  // 2. Buat wrapper carousel horizontal (Mengganti inline style dengan CSS Class)
  const wrapper = document.createElement("div");
  wrapper.className = "multi-preview";
  wrapper.style.display = "flex";
  wrapper.style.overflowX = "auto";
  wrapper.style.scrollBehavior = "smooth";
  wrapper.style.alignItems = "center";
  wrapper.style.position = "relative";
  wrapper.style.width = "100%";
  wrapper.style.height = "100%";

  containerArray.appendChild(wrapper);
  let loadedCount = 1;

  // 3. Render setiap gambar ke dalam thumbnail preview
  files.forEach((file) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const thumbImg = new Image();
      thumbImg.src = e.target.result;
      thumbImg.className = "preview-thumb-img";
      thumbImg.onload = () => {
        multiBool = true;
        processExifData(thumbImg, () => {
          const canvas = document.createElement("canvas");
          canvas.className = "preview-thumb";

          downloadButton.disabled = true;
          toggleAdvancedButton.disabled = true;
          downloadButton.textContent = `${file.name} (${loadedCount++}/${
            files.length
          })`;

          const thumbMax = 300;
          const ratio = thumbImg.width / thumbImg.height;

          if (thumbImg.width >= thumbImg.height) {
            canvas.width = Math.min(thumbImg.width, thumbMax);
            canvas.height = Math.round(canvas.width / ratio);
          } else {
            canvas.height = Math.min(thumbImg.height, thumbMax);
            canvas.width = Math.round(canvas.height * ratio);
          }

          createFramedImage(currentExifData, canvas, thumbImg);
          canvas._sourceImage = thumbImg;
          canvas._exifData = { ...currentExifData };

          // 4. Bungkus tiap item (wrapperItem)
          const wrapperItem = document.createElement("div");
          wrapperItem.className = "thumb-wrapper";
          // canvas.style.width = "100%";
          // canvas.style.height = "auto";
          // canvas.style.borderRadius = "8px";
          // canvas.style.border = "1px solid #333";
          // canvas.style.boxShadow = "0 2px 6px rgba(0, 0, 0, 0.6)";
          // canvas.style.backgroundColor = "#000";

          wrapperItem.appendChild(canvas);

          // 5. Label nama file
          const label = document.createElement("p");
          label.className = "file-title";
          label.textContent = file.name;
          label.title = file.name;

          wrapperItem.appendChild(label);
          wrapper.appendChild(wrapperItem);
        });
        applyManualData();
      };
    };
    reader.readAsDataURL(file);
    setTimeout(() => {
      downloadButton.disabled = false;
      toggleAdvancedButton.disabled = false;
      downloadButton.textContent = "Simpan";
    }, 800);
  });
  // 6. Jalankan applyManualData setelah semua file selesai dimuat (disederhanakan)
  Promise.all(
    files.map(
      (f) =>
        new Promise((resolve) => {
          const r = new FileReader();
          r.onload = () => resolve();
          r.readAsDataURL(f);
        }),
    ),
  ).then(() => {
    if (typeof applyManualData === "function") {
      applyManualData();
    }
  });
}

let multiBool = false;
// --- EXIF PROCESSING ---
function processExifData(imgElement, callback) {
  if (imgElement.exifdata) delete imgElement.exifdata;
  EXIF.getData(imgElement, function () {
    const allTags = EXIF.getAllTags(this);
    let make = allTags.Make || "";
    let model = allTags.Model || "";
    let device = (make + " " + model).trim().replace(/\s+/g, " ");
    // let device = model.trim().replace(/\s+/g, " ");
    if (
      device === "vivo I2220" ||
      device === "Google I2220" ||
      device === "I2220" ||
      device == "iQOO iQOO 12"
    )
      device = "iQOO 12";
    else if (device === "Google Mi A1" || device === "Mi A1")
      device = "Xiaomi Mi A1";
    else if (device === "Google Mi 5X" || device === "Mi 5X")
      device = "Xiaomi Mi 5X";

    const width =
      allTags.PixelXDimension || allTags.ImageWidth || imgElement.naturalWidth;
    const height =
      allTags.PixelYDimension ||
      allTags.ImageHeight ||
      imgElement.naturalHeight;

    const focalActual = formatFocalLength(allTags.FocalLength, device);
    const resolution = formatResolution(width, height, device, focalActual);
    const aperture = formatAperture(allTags.FNumber, device);
    const shutterSpeed = formatShutterSpeed(allTags.ExposureTime);
    const iso = formatIso(allTags.ISOSpeedRatings);

    const focalEqRaw =
      allTags.FocalLengthIn35mmFilm || allTags.FocalLengthIn35mmFormat;
    const focalEq = focalEqRaw ? `${focalEqRaw}mm equivalent` : "";

    // if (!manualFields.device.value)
    if (multiBool === false) {
      manualFields.device.value = device;
      manualFields.resolution.value = resolution;
      manualFields.aperture.value = aperture;
      manualFields.shutterSpeed.value = shutterSpeed;
      manualFields.iso.value = iso;
      manualFields.focalActual.value = focalActual;
      manualFields.focalEq.value = focalEq;
    } else {
      manualFields.device.value = "";
      manualFields.resolution.value = "";
      manualFields.aperture.value = "";
      manualFields.shutterSpeed.value = "";
      manualFields.iso.value = "";
      manualFields.focalActual.value = "";
      manualFields.focalEq.value = "";
    }


    currentExifData = {
      device: device,
      resolution,
      aperture,
      shutterSpeed,
      iso,
      focalActual,
      focalEq,
    };

    if (callback) callback();
  });
}

// --- ENSURE WATERMARK READY ---
function ensureWMReady() {
  return new Promise((resolve) => {
    if (!wmImageFile) {
      const fallbackWM = new Image();
      fallbackWM.src =
        "data:image/jpeg;base64,";
      fallbackWM.onload = () => {
        wmImageFile = fallbackWM;
        resolve();
      };
    } else if (wmImageFile.complete) {
      resolve();
    } else {
      wmImageFile.onload = () => resolve();
    }
  });
}

// --- APPLY MANUAL DATA ---
async function applyManualData() {
  applyManualButton.disabled = true;

  const manualData = {
    device: manualFields.device.value || "",
    resolution: manualFields.resolution.value || "",
    aperture: manualFields.aperture.value || "",
    shutterSpeed: manualFields.shutterSpeed.value || "",
    iso: manualFields.iso.value|| "",
    focalActual: manualFields.focalActual.value || "",
    focalEq: manualFields.focalEq.value|| "",
  };

  await ensureWMReady();

  // === Mode Single File ===
  if (filesToProcess.length === 1) {
    currentExifData = { ...manualData };
    createFramedImage(currentExifData, previewCanvas);
    applyManualButton.disabled = false;
    return;
  }

  // === Mode Multi File ===
  const wrapper = document.querySelector("#frameContainerArray .multi-preview");
  if (!wrapper) return;

  const thumbs = wrapper.querySelectorAll("canvas.preview-thumb");

  thumbs.forEach((canvas) => {
    const img = canvas._sourceImage;
    const exif = canvas._exifData || {};

    // Hanya update nama device (dan WM size sudah otomatis dari slider)
    const data = {
      device:  manualData.device || exif.device || "",
      resolution: manualData.resolution || exif.resolution || "",
      aperture: manualData.aperture || exif.aperture || "",
      shutterSpeed: manualData.shutterSpeed || exif.shutterSpeed || "",
      iso: manualData.iso || exif.iso || "",
      focalActual: manualData.focalActual || exif.focalActual || "",
      focalEq: manualData.focalEq || exif.focalEq || "",
    };

    createFramedImage(data, canvas, img);
  });

  applyManualButton.disabled = false;
}

