// --- CREATE FRAMED IMAGE ---
function createFramedImage(data, targetCanvas, imgElement = null) {
  const img = imgElement || imgOriginal;
  const W = img.naturalWidth;
  const H = img.naturalHeight;
  if (W === 0 || H === 0) return;

  // ===== OUTER FRAME SETTINGS =====
  const OUTER_FRAME_RATIO = ratioSelect.value;       
  const OUTER_ROTATE = orientationSelect.value;     
  const OUTER_FRAME_SIZE = paddingSlider.value;       
  const OUTER_FRAME_COLOR = colorManual.value;

  const FRAME_HEIGHT = Math.max(Math.round(0.1028 * W - 0.0005 * H), 50);
  const PADDING_X = Math.max(15, Math.round(W * 0.036));
  const FONT_L = Math.round(FRAME_HEIGHT * 0.28);
  const FONT_LT = Math.round(FRAME_HEIGHT * 0.26);
  const FONT_LB = Math.round(FONT_LT * 0.52);
  const FONT_RT = Math.round(FRAME_HEIGHT * 0.2);
  const FONT_RB = Math.round(FONT_RT * 0.8);
  // const canvasWidth = W;
  // const canvasHeight = H + FRAME_HEIGHT;
  const innerWidth = W;
  const innerHeight = H + FRAME_HEIGHT;
  const innerRatio = innerWidth / innerHeight;

  let outerWidth, outerHeight;
  // const OUTER_FRAME_RATIO = outerWidth / outerHeight

  const paddingPercent = parseFloat(OUTER_FRAME_SIZE) / 100;
  const padding = (Math.min(innerWidth, innerHeight) * paddingPercent) / 2;

  let frameRatio = 1;
  if (OUTER_FRAME_RATIO !== "original") {
    const [rw, rh] = OUTER_FRAME_RATIO.split(":").map(Number);
    frameRatio = rw / rh;
  }
  if (OUTER_ROTATE === "vertikal") {
    frameRatio = 1 / frameRatio;
  }

  if (OUTER_FRAME_RATIO === "original") {
    outerWidth  = innerWidth + padding* 2;
    outerHeight = innerHeight + padding* 2;
  } else if (frameRatio < innerRatio) {
    outerWidth  = innerWidth + padding* 2;
    outerHeight = outerWidth / frameRatio;
  } 
  else {
    outerHeight = innerHeight + padding* 2;
    outerWidth  = outerHeight * frameRatio;
  }


  targetCanvas.width  = Math.round(outerWidth);
  targetCanvas.height = Math.round(outerHeight);
  const ctx = targetCanvas.getContext("2d");

  ctx.fillStyle = OUTER_FRAME_COLOR;
  ctx.fillRect(0, 0, targetCanvas.width, targetCanvas.height);
  const offsetX = Math.round((outerWidth  - innerWidth)  / 2);
  const offsetY = Math.round((outerHeight - innerHeight) / 2);
  ctx.drawImage(img, offsetX, offsetY, W, H);

  drawFrameContent(
    ctx,
    W,
    H,
    FRAME_HEIGHT,
    PADDING_X,
    FONT_L,
    FONT_LT,
    FONT_LB,
    FONT_RB,
    FONT_RT,
    data,
    offsetX,
    offsetY
  );
  updatePreviewSize(targetCanvas.width, targetCanvas.height);
}


function drawFrameContent(
  ctx,
  W,
  H,
  FRAME_HEIGHT,
  PADDING_X,
  FONT_L,
  FONT_LT,
  FONT_LB,
  FONT_RB,
  FONT_RT,
  data,
  offsetX,
  offsetY
) {
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(offsetX, offsetY + H, W, FRAME_HEIGHT);

  // Setup Exposure Text +++ Setup Exposure Text +++ Setup Exposure Text +++ Setup Exposure Text +++ Setup Exposure Text
  if (data.focalActual !== '' && !data.focalActual.endsWith(' ') && !data.focalActual.toLowerCase().endsWith('mm')) {
      let numericValue = data.focalActual.replace(/[m]/g, '').trim();
      data.focalActual = numericValue + "mm";
  }
  data.focalActual = data.focalActual.replace(/\s+/g, ' ').trim();
  if (data.aperture !== '' && !data.aperture.endsWith(' ') && !data.aperture.toLowerCase().startsWith('f/')) {
      let numericValue = data.aperture.trim();
      data.aperture = "f/" + numericValue;
  }
  data.aperture = data.aperture.replace(/\s+/g, ' ').trim();
  if (data.shutterSpeed !== '' && !data.shutterSpeed.endsWith(' ') && !data.shutterSpeed.endsWith('s') && !data.shutterSpeed.startsWith('1/')) {
      let numericValue = data.shutterSpeed.trim();
      data.shutterSpeed = "1/" + numericValue + "s";
  }
  data.shutterSpeed = data.shutterSpeed.replace(/\s+/g, ' ').trim();
  if (data.iso !== '' && !data.iso.endsWith(' ') && !data.iso.toUpperCase().startsWith('ISO')) {
      let numericValue = data.iso.trim();
      data.iso = "ISO" + numericValue;
  }
  data.iso = data.iso.replace(/\s+/g, ' ').trim();
  
  let partsRB = [];
  if (data.focalActual) {
    partsRB.push(data.focalActual);
  }
  if (data.aperture) {
    partsRB.push(data.aperture);
  }
  if (data.shutterSpeed) {
    partsRB.push(data.shutterSpeed);
  }
  if (data.iso) {
    partsRB.push(data.iso);
  }
  let exposureText = partsRB.join("  ");
  // Setup Exposure Text +++ Setup Exposure Text +++ Setup Exposure Text +++ Setup Exposure Text +++ Setup Exposure Text

  // Setup Resolution and Focal Length Equivalent Text +++ Setup Resolution and Focal Length Equivalent Text +++ Setup Resolution and Focal Length Equivalent Text
  if (data.resolution !== '' && !data.resolution.endsWith(' ') && !data.resolution.toUpperCase().endsWith('MP') && !data.resolution.endsWith('x Zoom') && !data.resolution.endsWith('X Zoom') && !data.resolution.endsWith('× Zoom')) {
      let numericValue = data.resolution.replace(/[xX×]/g, '').trim();
      if (data.resolution.includes('x') || data.resolution.includes('X')) {
        if (data.focalEq.trim() === '') {
          data.resolution = numericValue + "x Zoom";
        } else {
          data.resolution = numericValue + "x Zoom |";
        }
      } else if (data.resolution.includes('×')) {
        if (data.focalEq.trim() === '') {
          data.resolution = numericValue + "× Zoom";
        } else {
          data.resolution = numericValue + "× Zoom |";
        }
      } else {
          data.resolution = numericValue + " MP";
      }
  }
  data.resolution = data.resolution.replace(/\s+/g, ' ').trim();

  if (data.focalEq !== '' && !data.focalEq.endsWith(' ') && !data.focalEq.toLowerCase().endsWith('mm equivalent')) {
      let numericValue = data.focalEq.replace(/[m]/g, '').trim();
      data.focalEq = numericValue + "mm equivalent";
  }
  data.focalEq = data.focalEq.replace(/\s+/g, ' ').trim();

  let resolutionFocalEq = `${data.resolution} ${data.focalEq}`;
  if (data.resolution.trim() === "" && data.focalEq.trim() !== "") {
      resolutionFocalEq = `${data.focalEq}`;
  }
  // Setup Resolution and Focal Length Equivalent Text +++ Setup Resolution and Focal Length Equivalent Text +++ Setup Resolution and Focal Length Equivalent Text


  // Setup Variable +++ Setup Variable +++ Setup Variable +++ Setup Variable +++ Setup Variable
  let PADDING_X2;
  let lbText = manualFields.descrip.value || "";

  // Left Side Text Variables
  const lineSpacingL = FONT_LT * 0.47;
  const totalHeightL = FONT_LT + lineSpacingL + FONT_LB;
  let yDevice, yDescrip;
  // Left Side Text Variables

  // Right Side Text Variables
  const lineSpacingR = FONT_RT * 0.6;
  const totalHeightR = FONT_RT + lineSpacingR + FONT_RB;
  const yCenterR = H + FRAME_HEIGHT / 2.2;
  let yResolution, yResRT, yExposure;
  let outputRT = resolutionFocalEq;
  let outputRB = exposureText;
  let nullExpo;
  // Right Side Text Variables

  // Setup Variable +++ Setup Variable +++ Setup Variable +++ Setup Variable +++ Setup Variable


  // Setup Draw Text Left Side +++ Setup Draw Text Left Side +++ Setup Draw Text Left Side +++ Setup Draw Text Left Side
  if (lbText.trim() !== "") {
    ctx.fillStyle = "#111111";
    ctx.font = `bold ${FONT_LT}px ${nameFont}`;
    ctx.textAlign = "left";
    yDevice = offsetY + H + FRAME_HEIGHT / 2.2 + FONT_LT / 2;
  } else {
    ctx.fillStyle = "#111111";
    ctx.font = `bold ${FONT_L}px ${nameFont}`;
    ctx.textAlign = "left";
    yDevice = offsetY + H + FRAME_HEIGHT / 2.2 + FONT_L / 2;
  }

  function printLeftText(text) {
    if (lbText.trim() !== "") {
      // yResolution = yCenterR - totalHeightL / 2 + FONT_LT;
      yResolution = yDevice - totalHeightL / 2 + FONT_LB;

      if (text.trim() !== "") {
        ctx.fillText(text, PADDING_X + offsetX, yResolution);

        ctx.fillStyle = "#707070";
        ctx.font = `bold ${FONT_LB}px ${nameFont}`;
        ctx.textAlign = "left";
        yDescrip = yResolution + FONT_LB + lineSpacingL;
        ctx.fillText(lbText, PADDING_X + offsetX, yDescrip);
      } else {
        ctx.fillText(lbText, PADDING_X + offsetX, yDevice)
      }
    } else {
      ctx.fillText(text, PADDING_X + offsetX, yDevice);
    }
  }

  if (resolutionFocalEq.trim() !== "" && data.device.trim() == "" && exposureText.trim() == "") {
    printLeftText(resolutionFocalEq);

    resolutionFocalEq = "";
    outputRT = "";
    PADDING_X2 = PADDING_X / 2;
  } else {
    printLeftText(data.device);
    if (resolutionFocalEq.trim() === "" && exposureText.trim() === "")
      PADDING_X2 = PADDING_X / 2;
    else {
      PADDING_X2 = PADDING_X;
    }
  }
  // Setup Draw Text Left Side +++ Setup Draw Text Left Side +++ Setup Draw Text Left Side +++ Setup Draw Text Left Side


  // Setup Draw Text Right Side +++ Setup Draw Text Right Side +++ Setup Draw Text Right Side +++ Setup Draw Text Right Side
  ctx.font = `bold ${FONT_RT}px ${nameFont}`;
  ctx.fillStyle = "#111111";

  let resFocalWidth, resExposureWidth;
  if (exposureText !== "" && resolutionFocalEq.trim() === "") {
    resFocalWidth = ctx.measureText(exposureText).width;
    resExposureWidth = ctx.measureText(resolutionFocalEq).width;
  } else {
    resFocalWidth = ctx.measureText(resolutionFocalEq).width;
    resExposureWidth = ctx.measureText(exposureText).width;
  }

  let WPX = W - PADDING_X + offsetX;
  let pResFocal, pExposure, widthForWm;
  let xExposure, xResFocal;
  let PADDING_X3 = 0;
  if (resFocalWidth * FONT_RT > resExposureWidth * FONT_RB) {
    xResFocal = WPX;
    xExposure = WPX - resFocalWidth;
    pResFocal = "right";
    pExposure = "left";
    widthForWm = resFocalWidth;
  } else {
    PADDING_X3 = PADDING_X2 * 2;
    xResFocal = WPX - resExposureWidth * (FONT_RB / FONT_RT);
    xExposure = WPX;
    pResFocal = "left";
    pExposure = "right";
    widthForWm = resExposureWidth * (FONT_RB / FONT_RT);
  }

  ctx.textAlign = pResFocal;

  if (exposureText !== "") {
    if (resolutionFocalEq.trim() === "") {
      outputRT = exposureText;
      outputRB = "";
      yResolution = yCenterR + FONT_RT / 2.2;
      yResRT = yResolution + FONT_RT / 9;
      nullExpo = true;
    } else {
      yResolution = yCenterR - totalHeightR / 2 + FONT_RT;
      yResRT = yResolution;
      nullExpo = false;
    }
  } else if (exposureText.trim() === "") {
    yResolution = yCenterR + FONT_RT / 2.2;
    yResRT = yResolution + FONT_RT / 9;
    nullExpo = true;
  }
  ctx.fillText(outputRT, xResFocal, yResRT + offsetY);

  ctx.font = `bold ${FONT_RB}px ${nameFont}`;
  ctx.fillStyle = "#8c8c8c";
  ctx.textAlign = pExposure;
  yExposure = yResolution + FONT_RB + lineSpacingR;
  ctx.fillText(outputRB, xExposure, yExposure + offsetY);
  // Setup Draw Text Right Side +++ Setup Draw Text Right Side +++ Setup Draw Text Right Side +++ Setup Draw Text Right Side


  if (wmImageFile)
    drawWM(
      ctx,
      wmImageFile,
      W,
      PADDING_X,
      PADDING_X2,
      PADDING_X3,
      yResolution,
      widthForWm,
      FONT_L,
      FONT_RT,
      FONT_RB,
      nullExpo,
      offsetX,
      offsetY
    );
}

function drawWM(
  ctx,
  wm,
  W,
  PADDING_X,
  PADDING_X2,
  PADDING_X3,
  yResolution,
  widthForWm,
  FONT_L,
  FONT_RT,
  FONT_RB,
  nullExpo,
  offsetX,
  offsetY
) {
  const maxWMHeight = FONT_RT + FONT_RB;

  const wmScale = wmSize * Math.min(maxWMHeight / wm.height, 1);
  const wmWidth = wm.width * wmScale;
  const wmHeight = wm.height * wmScale;
  const xWM = W - PADDING_X - wmWidth - widthForWm - 1.5 * PADDING_X2 + offsetX;

  let yWM, yPipe;
  if (!nullExpo) {
    yWM = yResolution - wmHeight / 2 + maxWMHeight / 4 + offsetY;
    yPipe = yResolution - maxWMHeight / 2 + 1.22 * maxWMHeight + offsetY;
  } else {
    yWM = yResolution - wmHeight / 2 - maxWMHeight / 9 + offsetY;
    yPipe = yResolution - maxWMHeight + 1.35 * maxWMHeight + offsetY;
  }

  ctx.drawImage(wm, xWM, yWM, wmWidth, wmHeight);

  const xPipe = xWM + wmWidth + (1.4 * PADDING_X) / 2;
  ctx.save();
  ctx.translate(xPipe, yPipe);
  ctx.scale(0.36, 1);
  ctx.font = `bold ${maxWMHeight * 1.6}px "Pixelify Sans", sans-serif`;
  ctx.fillStyle = "#c2c2c2ff";
  ctx.textAlign = "left";
  ctx.fillText("|", 0, 0);
  ctx.restore();
}

function updatePreviewSize(canvasW, canvasH) {
  const container = previewArea;
  const frameWrap = frameContainer;
  const containerRect = container.getBoundingClientRect();
  const containerWidth = containerRect.width - 10;
  const containerHeight = containerRect.height - 10;
  if (
    canvasW <= 0 ||
    canvasH <= 0 ||
    containerWidth <= 0 ||
    containerHeight <= 0
  )
    return;

  const imageRatio = canvasW / canvasH;
  const containerRatio = containerWidth / containerHeight;
  let displayWidth, displayHeight;
  if (imageRatio > containerRatio) {
    displayWidth = containerWidth;
    displayHeight = containerWidth / imageRatio;
  } else {
    displayHeight = containerHeight;
    displayWidth = containerHeight * imageRatio;
  }
  frameWrap.style.width = `${displayWidth}px`;
  frameWrap.style.height = `${displayHeight}px`;
  placeholderText.style.display = "none";
}

// --- BATCH DOWNLOAD ---
async function handleBatchDownload() {
  downloadButton.disabled = true;
  toggleAdvancedButton.disabled = true;
  downloadButton.textContent = "Processing...";

  // === Mode Multi File ===
  const wrapper = document.querySelector("#frameContainerArray .multi-preview");
  const thumbs = wrapper
    ? wrapper.querySelectorAll("canvas.preview-thumb")
    : [];

  if (thumbs.length > 0) {
    for (let i = 0; i < thumbs.length; i++) {
      const canvas = thumbs[i];
      const fileName = filesToProcess[i]?.name || `image_${i + 1}`;
      const dataURL = canvas.toDataURL("image/jpeg", 0.95);
      const a = document.createElement("a");
      a.href = dataURL;

      downloadButton.textContent = `${fileName} (${i + 1}/${thumbs.length})`;

      const now = new Date();
      const pad = (num) => String(num).padStart(2, "0");
      const year = now.getFullYear();
      const month = pad(now.getMonth() + 1);
      const day = pad(now.getDate());
      const hours = pad(now.getHours());
      const minutes = pad(now.getMinutes());
      const seconds = pad(now.getSeconds());
      const timestamp = `${year}${month}${day}_${hours}${minutes}${seconds}`;

      const deviceName = (manualFields.device.value || "Device")
        .replace(/[^a-zA-Z0-9]/g, "_")
        .substring(0, 20);

      a.download = `EXIF_Frame_${deviceName}_${fileName
        .split(".")[0]
        .substring(0, 30)}_${timestamp}_Kyuziera.jpg`;
      a.click();

      await new Promise((r) => setTimeout(r, 200));
    }
    downloadButton.disabled = false;
    toggleAdvancedButton.disabled = false;
    downloadButton.textContent = "Berhasil Disimpan!";
    setTimeout(() => {
      downloadButton.textContent = "Simpan";
    }, 800);
    return;
  }

  // === Mode Single File ===
  if (filesToProcess.length === 1) {
    const dataURL = previewCanvas.toDataURL("image/jpeg", 0.95);
    const a = document.createElement("a");
    a.href = dataURL;
    const file = filesToProcess[0];
    const timestamp = new Date()
      .toISOString()
      .slice(0, 19)
      .replace(/[-T:]/g, "");
    const deviceName = manualFields.device.value
      .replace(/[^a-zA-Z0-9]/g, "_")
      .substring(0, 20);
    a.download = `EXIF_Frame_${deviceName}_${file.name
      .split(".")[0]
      .substring(0, 30)}_${timestamp}_Kyuziera.jpg`;
    a.click();

    downloadButton.textContent = "Berhasil Disimpan!";
    setTimeout(() => {
      downloadButton.disabled = false;
      toggleAdvancedButton.disabled = false;
      downloadButton.textContent = "Simpan";
    }, 800);
    return;
  }

  // Jika tidak ada file
  downloadButton.textContent = "Tidak ada file!";
  setTimeout(() => {
    downloadButton.disabled = false;
    toggleAdvancedButton.disabled = false;
    downloadButton.textContent = "Simpan";
  }, 800);
}

