toggleAdvancedButton.addEventListener("click", () => {
  const isHidden =
    advancedControls.classList.contains("hidden-controls");
  if (isHidden) {
    advancedControls.classList.remove("hidden-controls");
    advancedControls.classList.add("visible-controls");
    toggleAdvancedButton.textContent = "Hidden";
    toggleAdvancedButton.classList.add("on");
  } else {
    advancedControls.classList.remove("visible-controls");
    advancedControls.classList.add("hidden-controls");
    toggleAdvancedButton.textContent = "Frame";
    toggleAdvancedButton.classList.remove("on");
  }
});